<section class="card"><h2><?= e(t('Create a recurring schedule')) ?></h2><form class="form-grid" method="post" action="/salary/recurring"><?= csrf_field() ?><label><?= e(t('Title')) ?><input name="title" maxlength="150" placeholder="<?= e(t('Your own salary or subscription')) ?>" required></label><label><?= e(t('Kind')) ?><select name="kind"><option value="income"><?= e(t('Income')) ?></option><option value="expense"><?= e(t('Expense')) ?></option></select></label><label><?= e(t('Amount (LKR)')) ?><input name="amount" type="number" min="0.01" max="9999999999.99" step="0.01" required></label><label><?= e(t('First date')) ?><input name="next_date" type="date" required></label><label><?= e(t('Repeat')) ?><select name="interval"><option value="monthly"><?= e(t('Monthly')) ?></option><option value="weekly"><?= e(t('Weekly')) ?></option><option value="yearly"><?= e(t('Yearly')) ?></option><option value="daily"><?= e(t('Daily')) ?></option></select></label><label><?= e(t('Income type (income only)')) ?><select name="income_type"><option value="salary"><?= e(t('Salary')) ?></option><option value="freelance"><?= e(t('Freelance')) ?></option><option value="business"><?= e(t('Business')) ?></option><option value="other"><?= e(t('Other')) ?></option></select></label><label><?= e(t('Expense account (expense only)')) ?><select name="account_id"><option value=""><?= e(t('Choose for expense')) ?></option><?php foreach ($accounts as $account): ?><option value="<?= e($account['id']) ?>"><?= e($account['name']) ?></option><?php endforeach; ?></select></label><label><?= e(t('Expense category (expense only)')) ?><select name="category_id"><option value=""><?= e(t('Choose for expense')) ?></option><?php foreach ($categories as $category): ?><option value="<?= e($category['id']) ?>"><?= e($category['name']) ?></option><?php endforeach; ?></select></label><label class="full"><span><input type="checkbox" name="active" value="1"> <?= e(t('Enabled — record due entries automatically when this app is in use')) ?></span></label><div class="full"><button><?= e(t('Create schedule')) ?></button></div></form><p class="footnote"><?= e(t('Create either a reminder in Financial Calendar or an automatic recurring expense for the same bill, so you do not record the same payment twice through two separate workflows.')) ?></p></section>
<section class="card"><h2><?= e(t('Recent generated entries')) ?></h2><?php if (!$history): ?><p class="muted"><?= e(t('No recurring entries have been recorded.')) ?></p><?php else: ?><div class="table-wrap"><table><thead><tr><th><?= e(t('Schedule')) ?></th><th><?= e(t('Occurrence date')) ?></th><th><?= e(t('Linked record')) ?></th></tr></thead><tbody><?php foreach ($history as $entry): ?><tr><td><?= e($entry['title']) ?><small><?= e(ucfirst($entry['kind'])) ?></small></td><td><?= e($entry['due_date']) ?></td><td><?= $entry['income_id'] ? t('Income #').e($entry['income_id']) : ($entry['expense_id'] ? t('Expense #').e($entry['expense_id']) : t('Record removed · occurrence kept to prevent duplication')) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
